 static void ClearAll(){var f=new Fixture();var service=f.Open();var preview=f.Preview(service);Check(B(preview,"supported")&&B(preview,"requiresSteamExit")&&!Directory.Exists(f.E.Data),"force preview binds current account and is read only");byte[] other=File.ReadAllBytes(f.OtherFile);f.OS.OnStop=()=>Put(f.AccountFile,Fixture.Vdf.Replace("\"before\"","\"steam-flush\""));var result=f.Apply(service,preview);var options=SteamLaunchOptions.Read(f.Steam,44);Check(S(result,"status")=="completed"&&B(result,"steamCleared")&&options.LaunchOptions=="","force clears ALL current App108600 flags including unrelated custom options");Check(other.SequenceEqual(File.ReadAllBytes(f.OtherFile))&&File.ReadAllText(f.AccountFile).Contains("-foreign-other-game")&&File.ReadAllText(f.AccountFile).Contains("steam-flush"),"other account, other app and unrelated exit-time VDF flush stay untouched");Check(!File.ReadAllText(f.E.Config).Contains("-agent")&&!File.ReadAllText(f.E.Config).Contains("-javaagent")&&File.ReadAllText(f.E.Config).Contains("-Xmx8g")&&File.ReadAllText(f.E.Config).Contains("\"custom\":17"),"force removes independent game launch agents and preserves heap and custom JSON");Check(!SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods)).Any(id=>id=="ZombieBuddy"||id=="Viewpoint")&&SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods)).Contains("Ordinary"),"known core selections return to off while unrelated Lua selection remains");Check(f.OS.Stops==1&&f.OS.Starts==1&&!B(result,"recoveryPending"),"single force consent performs one normal exit and reopen");Check(!Json.Serialize(new[]{preview,result}).Contains("secret")&&!Json.Serialize(new[]{preview,result}).Contains("\"account\""),"force DTOs expose no launch secrets or account identity");var duplicate=f.Apply(service,preview);Check(S(duplicate,"status")!="completed"&&f.OS.Stops==1,"repeated stale force clicks never apply twice");}
